 result=rpc('authorBatch',**req);assert result['checkpointSaved'];saved=checkpoint.read_bytes();assert json.loads(saved)['changes'];now=read();assert next(v for v in now['nodes'] if v['id']=='body')['source']==req['edits'][0]['text'] and now['implementationDescription']==req['edits'][1]['text'];primary();f.checked('다른 본문/구조 편집/오래된 owner proof는 미적용이며 허용 본문·설명만 한 후보/CAS로 저장하고 primary와 원본을 보존한다')
 assert rpc('settledAuthorBatch',**req)['settled'];primary_req={k:v for k,v in req.items() if k not in ['view','viewBinding']};assert not rpc('settledAuthorBatch',**primary_req)['settled'];other_req={**req,'view':'2','viewBinding':other['authorBinding']};assert not rpc('settledAuthorBatch',**other_req)['settled'];assert checkpoint.read_bytes()==saved;primary();f.checked('지속 저장 receipt의 UI surface는 독립 창별로 구분하여 primary나 다른 창이 같은 attempt를 완료로 채택하지 않는다')
 epoch=binding()['viewBinding'];f.invoke('closeEditorView',{'view':'1','id':owner});reopened=open_view();assert reopened['authorBinding']!=epoch;rpc('read',False,id=graph,**{**binding(),'viewBinding':epoch});rpc('authorBatch',False,**req);assert rpc('settledAuthorBatch',**{**req,**binding()})['settled'];assert checkpoint.read_bytes()==saved;primary();f.checked('닫힌 view slot을 같은 정보로 재사용해도 이전 binding 요청은 거절하며 새 명시적 binding에서만 기존 완료 근거를 조회한다')
